# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 vilis','廉价的；低劣的；不值钱的']]
W=[
E('vile','/vaɪl/','令人作呕的；恶劣的；卑鄙的','不只是“不好”，而是让人本能地皱眉、厌恶，觉得实在糟透了。','经古法语 vil、盎格鲁法语 ville，来自拉丁 vilis 廉价、低劣。价值低的评价引申到品质、感官和道德层面的恶劣。',B+[['古法语 vil / 盎格鲁法语 ville','低劣；可耻；令人厌恶'],['英语 vile','极难闻或难受的；道德上卑鄙的']],'a vile smell 是恶臭，vile behaviour 是卑劣行为，a vile mood 是糟糕透顶的心情。它表示很强的负面评价，不适合拿来平静描述价格便宜；词源中的廉价不等于现代的主要用法。','a vile smell；vile abuse；a vile mood；vile behaviour。','cheap 可以只是价格低，vile 则表达强烈厌恶。villa 别墅、village 村庄来自另一条拉丁 villa 路线，不是这个低劣词根。',('A vile smell rose from the blocked drain.','堵住的排水口冒出一股恶臭。'),('She condemned the vile abuse directed at the volunteers.','她谴责了那些针对志愿者的恶毒辱骂。'),sources=['https://www.etymonline.com/word/vile','https://www.oxfordlearnersdictionaries.com/definition/english/vile']),
E('vilify','英 /ˈvɪlɪfaɪ/；美 /ˈvɪləfaɪ/','诋毁；恶意贬损','用话把一个人的形象往泥里按，让别人觉得他坏透了、毫无价值。','来自后期拉丁 vilificare：vilis 低劣 + facere 使、做。现代可联想 vile 与 -ify，但历史上借入的是已有的拉丁动词。',B+[['后期拉丁 vilis + facere → vilificare','贬低价值；视为低劣'],['英语 vilify','用恶毒言辞贬损名誉或形象']],'它常用于讨论舆论攻击，尤其是把人描述成极坏的角色。vilify 不只是指出具体错误，而带有恶毒贬损的意味。过去式 vilified 要把词尾 y 改为 i；读音也别照 vile 的 /aɪ/ 念，开头是 /vɪl/。','vilify someone；be vilified in the press；vilify someone as a traitor。','criticize 可以理性批评，vilify 强调把对象说得很坏。它与 defame 有交集，但单凭日常词义不能判断是否满足某种法律责任。',('The article vilified the scientist without addressing her evidence.','文章恶意诋毁了那位科学家，却没有回应她的证据。'),('He urged both sides to debate the policy instead of vilifying each other.','他敦促双方讨论政策，而不是互相诋毁。'),sources=['https://www.etymonline.com/word/vilify','https://www.ahdictionary.com/word/search.html?q=vilify','https://dictionary.cambridge.org/dictionary/english/vilify']),
E('vilification','英 /ˌvɪlɪfɪˈkeɪʃən/；美 /ˌvɪləfəˈkeɪʃən/','诋毁；恶意贬损的行为','把人持续说成坏人，这一整套语言攻击就是 vilification。','来自中世纪拉丁 vilificatio，关联后期拉丁 vilificare 的名词支线。与英语 vilify 对应，但不是仅凭现代拼写推出借入顺序。',B+[['后期拉丁 vilificare → 中世纪拉丁 vilificatio','贬低 → 贬低、侮辱的行为'],['英语 vilification','公开或持续的恶意贬损']],'常与 public、personal、campaign of 连用。它可以指一次严重的攻击，也可以概括长期的污名化过程。写作时，如果只想说别人不同意自己，用 disagreement 就够；vilification 的指控明显重得多。','public vilification；personal vilification；a campaign of vilification。','criticism 是批评，vilification 是恶意把人贬得很坏；humiliation 则着重被羞辱的处境或感受，不一定通过名誉攻击造成。',('She continued her work despite a campaign of public vilification.','尽管遭到一连串公开诋毁，她仍继续工作。'),('The discussion turned from criticism of the proposal to personal vilification.','讨论从批评提案转成了对个人的恶意攻击。'),sources=['https://www.etymonline.com/word/vilification','https://dictionary.cambridge.org/us/dictionary/english/vilification']),
E('revile','/rɪˈvaɪl/','辱骂；痛斥；强烈谴责','带着厌恶向一个人倾倒恶毒的话，或把某件事骂得一文不值。','来自古法语 reviler，关联 aviler 使低贱、贬低与 vil 低劣。re- 在这里可能起加强作用，不是现代英语里“再骂一次”的意思。',B+[['古法语 aviler / reviler','贬低；鄙视、辱骂'],['中古英语 revilen → 英语 revile','用恶毒语言攻击；强烈谴责']],'常见被动形式 be reviled，尤其在历史人物、公众争议和评论里。它突出强烈的言语敌意；不必先有一次辱骂才可以用。与 vilify 相比，revile 更容易让人想到直接痛骂或普遍唾骂，两者也有重叠。','be widely reviled；revile someone for something；admired by some and reviled by others。','reveal 是揭露，revile 是辱骂；revive 是恢复活力。开头相似没有让它们变成同一词族。',('The reformer was praised by supporters and reviled by opponents.','那位改革者受到支持者赞扬，也遭到反对者痛斥。'),('Rather than revile the referee, the captain asked for an explanation.','队长没有辱骂裁判，而是要求对方作出解释。'),sources=['https://www.etymonline.com/word/revile','https://en.wiktionary.org/wiki/revile','https://www.oxfordlearnersdictionaries.com/definition/english/revile'])
]
ROOT=dict(id='C1637',meaning='廉价；低劣；可鄙',core='VIL = LOW IN VALUE / BASE',image='原先是把东西估得很低，后来转成把品质评得很差，再转成用语言把一个人的形象贬到最低。',intro='来自拉丁 vilis，最初的廉价、低价值之意发展出低劣、卑鄙、令人厌恶等评价。现代核心词 vile 是强烈形容词；vilify 与 revile 则把负面评价变成对人的语言攻击。',forms='vile 的 i 读 /aɪ/，vilify 开头读 /vɪl/；revile 仍以 /vaɪl/ 为重读部分。vilification 的重音落在 -cation 一带。不要因为 villa、village、villain 看起来相近就混作直系同源。',branches=[['强烈的负面评价','vile'],['贬损一个人的形象','vilify、vilification'],['恶毒言语攻击','revile']],contrasts='vile 是说某物令人厌恶；vilify 是把对象说得低劣；revile 强调恶毒的痛骂或谴责。批评不一定达到诋毁或辱骂的程度。',practice='The review criticized the decision without vilifying the people behind it.\n\n这篇评论批评了那个决定，但没有诋毁作出决定的人。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_vil',[ROOT]),('words_vil',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
